namespace ThisIsMyPC.App.ViewModels;

/// <summary>Lessons explain a module through concrete uses rather than a fixed section template.</summary>
public static class SetupLessons
{
    public static SetupLessonViewModel For(string name, string description) => name switch
    {
        "Windows Annoyances" => new(name, "Windows Annoyances",
            "A suggestion to try another Microsoft product is an advertisement, even when it appears in Settings. Windows puts promotions in several places, each with its own switch.\n\nOpen this module and search for suggestions. Read the matching setting, change it, and check the pending change before applying.\n\nIf another promotion appears later, note where it appeared. Start, Settings, and the lock screen have separate controls."),
        "Privacy & Telemetry" => new(name, "Privacy & Telemetry",
            "Windows separates required diagnostic data from optional data. This module also controls activity tracking and advertising personalization.\n\nOpen this module and find Diagnostic data. Compare the current value with the available choices; some depend on your Windows edition.\n\nThe pack limits optional collection. Check privacy settings inside newly installed apps too, because Windows cannot control every app's own collection."),
        "Windows Update" => new(name, "Windows Update",
            "The pack selects Notify before download, keeps Windows on its current feature release, excludes drivers, and limits automatic restarts.\n\nOpen this module to review those choices. If you keep the release pin, remove it before that release stops receiving security fixes. Check for updates regularly when downloads wait for you.\n\nSet active hours around when you use the PC to reduce restart interruptions."),
        "Software" => new(name, "Software",
            "Not everything installed on your PC is there because you wanted it. Windows includes apps of its own, and your PC manufacturer may have added more. An app you never open can still add background services, startup entries, and scheduled tasks. You also may have installed apps over time that you do not want or need anymore.\n\nAn Installed App has files saved on your PC. A Process is a running instance of a program, using memory and potentially processor time. Having an app installed does not mean its main program must run all day. Removing its files and stopping its background activity solve different problems.\n\nApps can register instructions that launch programs without you opening them. These are often broadly referred to as Autoruns. They can launch programs when Windows boots, when you sign in, or when a scheduled time or another event occurs. Boot means Windows starting; sign-in means entering your account. One app can register several Autoruns.\n\nYou do not have to uninstall an app to stop this unwanted background activity. You can often disable its Autoruns and keep the app available to open yourself. That is why Software and Startup & Services belong together.\n\nFor example, you might use a game launcher on weekends, but it runs in the background all week. If you disable its sign-in entry, that entry no longer opens the launcher every time you enter Windows. You can still open the launcher to play. A separate updater or service might continue running, so the next lesson checks those entries too.\n\nStart with an app you recognize. Decide whether you want to keep using it. If you do, follow it into Startup & Services to examine its automatic launches. If you no longer want it, uninstalling removes the app instead. Keeping an app enabled can also be useful: a messaging app may need to run in the background to notify you.\n\nThe Software page has three tabs. App Catalog contains supported programs you can install or uninstall through this app. Select Installed to see catalog entries found on your PC. This is not a complete list of every installed program. If an app is missing, look in Windows Settings under Apps > Installed apps.\n\nWindows Apps contains the supported Windows app packages, including bundled apps such as Clipchamp, News, and Weather. A Package is the unit Windows uses to install and maintain an app. Read an app's description before deciding whether to remove it. If you use Clipchamp to edit videos, keep it. If you never use it, removing it frees its installed storage.\n\nChoose Remove to add a Windows app to the pending list. Pending means the action is selected but has not run yet. These removals affect every account on the PC and stop the package being added automatically to new accounts. Save anything you need from the app before applying the removal. History cannot undo an uninstall. Apps with a Store listing have a reinstall option here, but reinstalling does not guarantee recovery of their previous data.\n\nUpdates lists available updates reported by Windows Package Manager, also called winget. This is Microsoft's tool for finding and managing software packages. It does not manage every app on your PC. If you disable an app's own updater later, you still need a way to keep that app updated.\n\nAt the end of the tutorial, the Desktop Grand Pack combines many cleanup choices into one preset. A Preset is a saved collection of changes you can review together. Its app removals include Clipchamp, News, Weather, Copilot, and Microsoft 365 Hub when installed. Clear any app you want to keep before applying the pack.\n\nContinue to Startup & Services with an app you want to keep. The next lesson explains how to identify its Autoruns and decide which ones you need."),
        "Security" => new(name, "Security",
            "Use this module to check antivirus, sign-in, and app protection settings. An antivirus scan can use CPU and disk while doing necessary work.\n\nIf Windows reports a protection problem, find that protection here and inspect its state. Read the setting before changing it; hiding a notification does not repair the protection."),
        "Network & Firewall" => new(name, "Network & Firewall",
            "Connections lists your network adapters. DNS controls which service looks up website addresses. Firewall shows the profiles and rules controlling network access.\n\nOpen Connections and identify the adapter carrying your connection. Check its DNS settings before changing them. VPN software can add adapters and replace DNS settings, so identify unfamiliar entries before disabling them."),
        "Startup & Services" => new(name, "Startup & Services",
            "Installing software often gives it ways to run without you opening it. These automatic-launch entries are broadly called Autoruns. An Autorun is an instruction, not proof that its program is running now. Entries accumulate as you install software, and one app can leave several different instructions for Windows to follow.\n\nTask Manager shows two different parts of this picture. Its Processes page lists running programs and their current resource use. Its Startup apps page lists familiar entries you can enable or disable for sign-in. Disabling a Startup App leaves the app installed and blocks that launch entry. It does not disable every other way the app can start.\n\nThe System Tray is the area beside the clock where some programs display icons. The overflow menu holds additional icons. Many background programs have no tray icon at all. Hiding an icon only changes its visibility; it does not stop the program. Choosing Exit from an app's tray menu may stop it now, but its Autoruns can bring it back later.\n\nA Scheduled Task tells Windows to perform an Action when a Trigger occurs. The Action might open an updater. The Trigger might be boot, sign-in, a daily time, an idle PC, or a particular event. Task Scheduler is the Windows tool that manages these tasks. They are separate from Task Manager's Startup apps list. A task can run briefly and finish, so you may never see it in the tray.\n\nA Service is a background program managed by Windows. It can run without a window or tray icon, and some services start before anyone signs in. Services support things such as printing, hardware controls, and software updates. A service's Startup Type controls how it can start. Automatic allows Windows to start it automatically. Manual allows it to start when requested; it does not mean only you can start it. Disabled prevents Windows from starting that service.\n\nWindows also reads automatic-launch instructions from Startup folders and the Registry. A Startup folder contains shortcuts that run at sign-in. The Registry is Windows' settings database; some entries there tell Windows which programs to launch. Drivers support hardware or system functions, while Extensions add behavior inside another program, such as File Explorer. Those can load without creating their own window. These mechanisms are less visible than Startup apps, but they are not all unnecessary background work.\n\nStartup & Services groups the entries it finds by type. Search for the app you chose in Software. The search covers the categories currently included by the page's filters. Windows and other Microsoft entries are hidden by default, so an empty result does not prove an app has no Autoruns.\n\nStart with an entry you recognize. The Publisher identifies who supplied the program. Its file path shows which program Windows will run. Its category tells you which launch mechanism it uses. For a Scheduled Task, the Trigger explains when it runs. Use those details together: a familiar name alone does not explain what an entry does.\n\nConsider the game launcher from Software. A sign-in entry may open its main window or leave it waiting in the tray. If you only play on weekends, you can disable that entry and open the launcher yourself when needed. A separate update task may still check for updates. Decide whether you want that task to continue, rather than assuming the sign-in change controls it too.\n\nDisabling an entry stages a change for review. Applying it changes future launches through that entry; it does not necessarily stop a program already running. After your next sign-in, check whether the unwanted launch stopped. Then open the app yourself and check the features you use. If you need the entry again, restore it. If you no longer want the app, return to Software to uninstall it.\n\nDo not judge cleanup by the number of entries disabled. An unused launcher and a service needed by your mouse can both appear here. Read what the entry supports. If you disable an updater, arrange to check for updates yourself. If an entry's purpose is unclear, leave it enabled while you investigate.\n\nThe Desktop Grand Pack includes a preset called Clean Boot. Here, that name means a specific collection of service and task changes. It includes Windows diagnostic-data collection and selected background jobs. Diagnostic data records how Windows and apps behave, including errors. Review the individual entries to see which functions will stop. For example, the pack disables Edge's updater services. Restore both before updating Edge. The preset name does not mean every listed function is useless on your PC.\n\nWindows Search is a separate, optional choice in the pack. Its Indexing Service builds a catalog of file names, file details, and supported contents. Like the index in a book, that catalog helps searches find information without reading every file each time. Maintaining it uses storage and background work as files change.\n\nDisabling Windows Search indexing reduces that work, but searches that depend on the index can become slower or lose results. Outlook configurations that use the Windows index can also be affected. Keep indexing if you rely on those searches. If you rarely use them, you can choose to disable it. You can also reduce the indexed locations in Windows instead of disabling the service.\n\nThe pack leaves Windows Search unchecked. Selecting it changes the service's Startup Type to Disabled. It does not delete the existing index or immediately stop a running service. Its effect on indexing begins when the service stops or Windows restarts."),
        "Explorer" => new(name, "Explorer",
            "File extensions distinguish files such as photo.jpg and photo.exe. Show extensions if you want to see the file type in its name.\n\nOpen this module and find Show file name extensions. Enable it, apply the change, then open a folder to compare the names.\n\nThe pack hides Widgets and restores the full right-click menu. Some changes may require an Explorer restart."),
        "Context Menus" => new(name, "Context Menus",
            "Apps add shortcuts to the menu you see when you right-click a file. Disabling an unused shortcut removes it from the menu without uninstalling the app.\n\nOpen this module and find an entry from an app you recognize. Disable it, apply the change, then right-click the same file again to check the result. Keep shortcuts you use often."),
        "Environment" => new(name, "Environment",
            "PATH is a list of folders Windows searches when you run a command. An installer can add its folder; an uninstaller can leave that entry behind.\n\nFind PATH and inspect the listed folders. If a command opens the wrong version, check whether an older installation appears earlier in that list. Remove an entry only after confirming which program uses it."),
        "Power Plans" => new(name, "Power Plans",
            "Choose when the screen turns off and when the PC sleeps. Power plans also affect processor behavior, heat, and energy use.\n\nOpen the active plan and find its screen and sleep settings. Set times that suit your work, then review the pending changes. Compare performance during your usual workload before keeping a performance change."),
        "Display" => new(name, "Display",
            "Adjust brightness or switch inputs on supported monitors without reaching for their buttons. You can link brightness across displays.\n\nChoose a monitor and move its brightness slider. Brightness changes immediately. Use Link brightness across displays if you want the sliders to move together. Controls unavailable here may still be available in the monitor's own menu."),
        "System Control" => new(name, "System Control",
            "Manufacturer software may combine promotions with useful hardware controls. Check which functions you need before uninstalling it.\n\nOpen System Control and check the detected hardware and supported companion options. Compare the functions you need with your manufacturer utility before replacing it. Many options target laptops and will be unavailable on a desktop."),
        "Lighting" => new(name, "Lighting",
            "Choose colors and effects for supported lighting devices here. Running two lighting controllers for the same device can make their settings conflict.\n\nSelect a detected device and try a fixed color before configuring an effect. If the color changes back, check Startup & Services for another lighting controller."),
        "Cooling" => new(name, "Cooling",
            "Cooling uses supported fan controls and FanControl integration. A fan curve sets fan speed in response to a temperature sensor.\n\nIdentify each fan and temperature sensor in the cooling controls before changing a curve. Make a small change, run your usual workload, and watch temperatures in Monitoring. A curve copied from another PC may not suit your cooling."),
        "Monitoring" => new(name, "Monitoring",
            "Compare load, temperatures, and fan speeds while doing the same task before and after a change. A reading taken at idle cannot show whether a game runs better.\n\nOpen Monitoring, note the readings at idle, then start your usual workload and watch how they change. Repeat that workload after a setting change. A missing sensor means no reading is available, rather than zero."),
        _ => new(name, name, description),
    };
}
